import createKindeClient from "@kinde-oss/kinde-auth-pkce-js"; 

(async () => {
	const kinde = await createKindeClient({
		client_id: process.env.CLIENT_ID,
		domain: process.env.DOMAIN,
		redirect_uri: process.env.REDIRECT_URI
	});
})
